() => {
  const out = [];
  for (const art of document.querySelectorAll('div[role="article"]')) {
    if (art.closest('div[role="article"]') !== art) continue;
    const actions = art.querySelector('[aria-label^="Actions for this post by"]');
    if (!actions) continue;
    const author = actions.getAttribute('aria-label').replace('Actions for this post by ', '').trim();
    let post_id = null, url = null, posted = null;
    for (const a of art.querySelectorAll('a[href]')) {
      const h = a.getAttribute('href') || '';
      let m = h.match(/\/posts\/(\d+)/) || h.match(/\/permalink\/(\d+)/) || h.match(/set=pcb\.(\d+)/);
      if (m && !post_id) { post_id = m[1]; }
      const t = (a.getAttribute('aria-label') || '').match(/^\w+day, \w+ \d+, \d{4}/);
      if (t && !posted) posted = t[0];
    }
    if (post_id) url = location.origin + location.pathname.replace(/\/$/, '') + '/posts/' + post_id + '/';
    return { sample_author: author, sample_post_id: post_id, sample_posted: posted, links_seen: art.querySelectorAll('a[href]').length };
  }
  return { none: true, articles: document.querySelectorAll('div[role="article"]').length };
}

() => {
  const arts = [...document.querySelectorAll('div[role="article"]')];
  const labels = arts.map(a => (a.getAttribute('aria-label') || '(no label)').slice(0, 60));
  const actionBtns = [...document.querySelectorAll('[aria-label*="Actions for this post"]')].map(e => ({tag: e.tagName, role: e.getAttribute('role'), label: e.getAttribute('aria-label').slice(0,50)}));
  return { articleLabels: labels, actionButtons: actionBtns.slice(0,5) };
}

() => {
  const posts = [];
  for (const btn of document.querySelectorAll('[aria-label^="Actions for this post by"]')) {
    const author = btn.getAttribute('aria-label').replace('Actions for this post by ', '').trim();
    let box = btn, id = null;
    for (let i = 0; i < 12 && box; i++) {
      box = box.parentElement;
      if (!box) break;
      for (const a of box.querySelectorAll('a[href]')) {
        const h = a.getAttribute('href') || '';
        const m = h.match(/\/posts\/(\d+)/) || h.match(/\/permalink\/(\d+)/) || h.match(/set=pcb\.(\d+)/);
        if (m) { id = m[1]; break; }
      }
      if (id) break;
    }
    if (!box) continue;
    let posted = null;
    for (const a of box.querySelectorAll('a[aria-label], a[title]')) {
      const v = a.getAttribute('aria-label') || a.getAttribute('title') || '';
      if (/\d{4}/.test(v) && /(day|Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)/.test(v)) { posted = v; break; }
    }
    const clone = box.cloneNode(true);
    clone.querySelectorAll('[role="article"]').forEach(c => c.remove());
    const text = (clone.innerText || '').replace(/\s+\n/g, '\n').trim();
    posts.push({ post_id: id, author, posted, photos: box.querySelectorAll('a[href*="/photo/"]').length, text_len: text.length, text_head: text.slice(0, 200) });
  }
  return { count: posts.length, posts };
}

